INSERT INTO books (book_name, cover_image_url, authors, publisher, category, isbn, language, num_pages, edition, price, discount_price, discount_percentage, rating, num_reviews, availability, description) VALUES
('চাঁদের পাহাড়', 'https://rokbucket.rokomari.io/ProductNew20190903/260X372/Chander_Pahar-Bibhutibhusan_Bandyopadhyay-8026c-346689.jpg', 'বিভূতিভূষণ বন্দ্যোপাধ্যায়', 'প্রিমিয়াম পাবলিকেশন্স', 'বয়স যখন ১২-১৭: রহস্য, গোয়েন্দা, থ্রিলার ও অ্যাডভেঞ্চার', NULL, 'বাংলা', 133, '1st Edition, 2023', 200.0, 100, '65% Off', NULL, 5, 'In Stock', '"মানুষের আয়ু মানুষের জীবনের ভুল মাপকাঠি। দশ বছরের জীবন সে উপভোগ করেছে দেড় বছরে।" - চাঁদের পাহাড় - বিভূতিভূষণ বন্দোপাধ্যায় দুঃসাহসিক অভিযানের স্বাদ পেতে চাঁদের পাহাড় বইটির জুড়ি নেই। শম্কর নামক ভারতীয় এক তরুণের আফ্রিকা মহাদেশের রোমাঞ্চকর অভিযান বইয়ের মূল প্লট। আফ্রিকার বিভিন্ন অঞ্চলের ভৌগোলিক স্থান, ভয়ংকর প্রাণী ও প্রাকৃতিক দৃশ্যের বাস্তব রূপ চিত্রায়িত করা হয়েছে উপন্যাসটিতে। রুদ্ধশ্বাস অভিযান, লোমহর্ষক ঘটনাক্রম, কষ্ট, সাহস, বীরত্ব, আর বন্ধুত্বের নানা উদাহরণ সৃষ্টির মাধ্যমে এগিয়ে যেতে থাকে উপন্যাসের কাহিনী। বাংলা ভাষার জনপ্রিয় এই উপন্যাসটি ছোট থেকে বড় প্রত্যেকের মধ্যেই সৃষ্টি করে রোমাঞ্চকর এক অনুভূতি।'),
('আরণ্যক', 'https://rokbucket.rokomari.io/ProductNew20190903/260X372/Aronnok-Bibhutibhushan_Bandyopadhyay-e6479-375433.jpg', 'বিভূতিভূষণ বন্দ্যোপাধ্যায়', 'প্রিমিয়াম পাবলিকেশন্স', 'চিরায়ত উপন্যাস', NULL, 'বাংলা', 268, '1st Published, 2024', 400.0, 200, '65% Off', NULL, 5, 'In Stock', 'এ এক প্রকৃতির গল্প। প্রকৃতির আনাচে-কানাচে লুকিয়ে থাকা সৌন্দর্যের গল্প। সভ্য সমাজের বাইরে থাকা প্রান্তিক, অবহেলিত জনগোষ্ঠীর গল্প। কিংবা একজন প্রকৃতিপ্রেমীর চোখে সৃষ্টিবিনাশ, আর প্রকৃতি ধ্বংসের এক ট্র‍্যাজিক স্টোরি। বিভূতি মশাই যে অতি উচ্চ মানসিকতার মার্জিত মানুষ ছিলেন, সেটার তার বইয়ের চরিত্র দেখলেই বোঝা যায়। সত্যচরণের মত এত মানবিক, নস্টালজিক, প্রকৃতিপ্রেমী চরিত্র সৃষ্টি করেছেন, ভাবা যায়! আমার আগেই বোঝা উচিত ছিলো যে, যেই লোক হাজারীর মত চরিত্র সৃষ্টি করতে পারে, তার দ্বারা সত্যচরণ সৃষ্টি করা কঠিন কিছু না। আর এটা কোনো উপন্যাসের কাতারেই পড়ে না। কোনো ভারী আখ্যান নেই, নেই কোনো শক্তপোক্ত চরিত্র, মানসিক-সাংসারিক টানাপোড়েন নেই। ও হ্যা, লেখকই তো প্রারম্ভে বলে দিয়ে গেছেন এটা। তবে এটায় লেখক তার যেই মোক্ষম অস্ত্রখানা প্রয়োগ করেছে, সেটা হলো ''হিপোটানাইজম''। সত্যচরণ যেমন হিপোটানাইজ হচ্ছে প্রকৃতির অপার সৌন্দর্য, ঝর্ণার কলকল ধ্বনি, লবটুবিয়ার জনমানুষের বিচিত্রতায়, জোৎস্নার ভয়ঙ্কর সৌন্দর্যে, ঠিক তেমনি আমিও হিপোটানাইজ হয়েছি প্রকৃতি আর সত্যচরণের গুন-রুপে। কাহিনির আগাগোড়া শুধুই প্রকৃতি। সাথে আছে জন বিচিত্রতা। বইটাকে এর ধরন অনুযায়ী তিন ভাগে ভাগ করতে পারি। প্রথমাংশে সত্যচরণ ধাতস্থ হয়েছেন ফুলবাড়ি বইহারে, আর মুগ্ধ হয়েছেন বন্য সৌন্দর্যে। দ্বিতীয়াংশে লেখক বুদ হয়েছেন মনুষ্য বিচিত্রতায়। আর তৃতীয় অংশ তো শুধুই ট্র‍্যাজেডি, ডিপ্রেসিভ। এতে আছে ভানুমতীর মত প্রকৃতির কন্যা—আর্য বংশধর, যুগলপ্রসাদের মত বৃক্ষানুরাগী, বৈঙ্কলের মত কাব্যানুরাগী, নৃত্যশিল্প অনুরাগী ধাতুরিয়া কিংবা কুন্তা-মঞ্চীর মত এস্থেটিক চরিত্র।কখনো গাঙ্গোতো''দের তিন মাস পর ভাত খাওয়ার উচ্ছাস দেখিয়া ঠোঁটের কোনে কিঞ্চিৎ হাসি উঁকি দিচ্ছে, কখনো অরণ্যভূমি বিরাণ হয়ে যাওয়া দেখে মুখ গোমড়া হয়ে আসছে — এটাই বিভূতিভূষণের জাদুকরী লেখার সার্থকতা। লেখক বইয়ের ভেতর যে বার্তা দিয়েছে, তাতে যে কেউ আমার মত বুদ হয়ে যাবে প্রকৃতির প্রেমে।'),
('আদর্শ হিন্দু হোটেল', 'https://rokbucket.rokomari.io/ProductNew20190903/260X372/Adarsha_Hindu_Hotel-Bibhutibhushan_Bandyopadhyay-208c3-375434.jpg', 'বিভূতিভূষণ বন্দ্যোপাধ্যায়', 'প্রিমিয়াম পাবলিকেশন্স', 'চিরায়ত উপন্যাস', NULL, 'বাংলা', 200, '1st Published, 2024', 350.0, 175, '65% Off', NULL, 5, 'In Stock', 'বিভূতিভূষণ বন্দ্যোপাধ্যায়ের উপন্যাসে প্রকৃতি নিজেই চরিত্র। প্রাণময়। কিন্তু আদর্শ হিন্দু-হোটেল-এ মানুষের জীবনই প্রধান ও প্রখর হয়ে উঠেছে। এই উপন্যাসের প্রধান চরিত্র হাজারি নিপীড়িত হয়, মিথ্যা চুরির অপবাদে পর্যুদস্ত হয়। তবু সে স্বপ্ন দেখে। খুব ব্যস্ত একটি রেলস্টেশন আর তার কাছে একটি ভাতের হোটেল, মূল ঘটনা এখানেই। শারীরিক কষ্ট, অনাদর আর অপমানে ক্লান্ত হাজারি তার সামান্য অবকাশ পার করে না সহকর্মী রতনঠাকুরের মতো গা এলিয়ে দিয়ে বা স্টেশনের ব্যস্ততা দেখে। সে চলে যায় চূর্ণী নদীর ধারের ঠাকুরবাড়িতে, কিংবা রাধাবল্লভ-তলায় নাটমন্দিরের নিভৃতিতে। স্বপ্ন দেখে ভবিষ্যতের। এমন কিছু উচ্চাশা নয় তার। হোটেলে কাজ করতে করতে সে গ্রাহক-ঠকানো দেখে। ডাল কম পড়লে তাতে ফ্যান মিশিয়ে দেয়, বাসী মাছ কড়া করে ভেজে চালিয়ে দেয় পরের দিন। এগুলো তার সরল মনকে আলোড়িত করেছে। সে ভেবেছে নিজেই একটা হোটেল করবে। সে হোটেলে এমন লোক-ঠকানো কাজ সে করবে না। সে হোটেল করেছে, জীবনে সাফল্য এসেছে, কিন্তু তার সরল সাধারণ মনটি হারিয়ে যায়নি। ব্যবসায়িক সাফল্য কিংবা বোম্বাইয়ের ডাক তাকে বিচলিত করেনি; বিচলিত করেছে তার প্রতিপক্ষ পদ্মদিদির প্রণতি : বিদায়বেলায় তার পা ছুঁয়ে তাকে প্রণাম করে যাওয়া। এই প্রণতিই তার জীবনের সবচেয়ে বড় পাওয়া। এই উপন্যাস তাঁর পক্ষেই লেখা সম্ভব, যিনি তাঁর দেশটিকে চোখ খুলে দেখেছেন, ভালোবেসেছেন; তার সূক্ষ্মাতিসূক্ষ্ম নানা দিক গভীরভাবে উপলব্ধি করেছেন।'),
('দেবযান', 'https://rokbucket.rokomari.io/ProductNew20190903/260X372/Devjan-Bibhutibhusan_Bandopadhyay-6cb84-434519.jpg', 'বিভূতিভূষণ বন্দ্যোপাধ্যায়', 'বর্ণলিপি প্রকাশনী', 'চিরায়ত উপন্যাস', '9789849837343', 'বাংলা', 232, '1st Edition 2024', 350.0, 179, '65% Off', NULL, 5, 'In Stock', 'দেবযান হলো প্রখ্যাত কথাসহিত্যিক বিভূতিভূষণ বন্দ্যোপাধ্যায় রচিত একটি বাংলা উপন্যাস। এই উপন্যাসে মৃত্যু ও জীবন উপলব্ধি নিয়ে রচিত। দেবযান নামটি সংস্কৃত শব্দ দেবযান থেকে এসেছে, যা আক্ষরিকভাবে ঈশ্বরের পথ হিসাবে অনুবাদ করা হয়েছে। এই পথ কোনো ফেরার পথ নয়, যেহেতু প্রাচীন ভারতীয় ধর্মগ্রন্থের ভিত্তিতে এই পথটি অতিক্রম করে একটি আত্মা মুক্তি পাবে। এই পথের বর্ণনা উপনিষদ এবং গীতাতেও রয়েছে। অন্য পথ পিতর ইয়ান নামে পরিচিত। কর্মের ফল কাটিয়ে উঠার জন্য এই পথটি আবার পৃথিবীতে ফিরে আসতে হবে। গীতা এই দুটি পথকে সাদা এবং কালো পথ হিসাবে উল্লেখ করে, এক যা শাশ্বত জীবনের দিকে পরিচালিত করে এবং অন্যটি বিশ্বকে প্রত্যাবর্তনের জন্য বাধ্য করে। সঠিক শ্লোক, তবে দেবযান নামটি গ্রহণ করে না ৷'),
